P = [
 dict(pmid='', doi='10.5194/amt-19-7487-2026', journal='Atmospheric Measurement Techniques', title='Intercomparison of nighttime aerosol optical depth retrievals from both reflectance-based and city light-based methods using VIIRS DNB data', short='VIIRS DNB nighttime AOD lunar reflectance vs city-light retrieval Dakar AERONET MODIS 2017-2019', design='Satellite retrieval evaluation', pm='Nighttime aerosol optical depth from VIIRS Day/Night Band by lunar-reflectance and artificial-light methods', geo='Senegal (Dakar), West Africa', endpoint='Agreement with solar and lunar AERONET AOD and daytime MODIS AOD', tier='C', basis='Satellite-fused', affil='University of North Dakota, USA; not stated in record', n='Compares two nighttime AOD retrievals from the VIIRS Day/Night Band over Dakar and Dakar Belair, 2017-2019: a lunar-reflectance method and a city-light method that reads aerosol from the upward diffusion of artificial light. Both were evaluated against solar and lunar AERONET and daytime MODIS. Both showed skill in locating over-ocean plumes and tracked AERONET quantitatively, and combining them raised nighttime sampling by more than 50%. No R2 or bias values are given in the abstract; cloud contamination and lunar-irradiance modelling remain unquantified error sources. Relevance: moderate - nighttime AOD would fill the half of the diurnal cycle that satellite-surface PM fusion currently leaves to sensors alone.', sub=corpus.SENS),
 dict(pmid='43040683', doi='10.1364/oe.618289', journal='Opt Express', title='Dynamic calibration method for the system constant of high-spectral-resolution lidar with airborne experimental verification.', short='Shanghai airborne HSRL time-varying system constant dynamic calibration roll angle disturbance', design='Remote sensing / lidar retrieval', pm='Aerosol attenuated backscatter from high-spectral-resolution lidar, ground and airborne', geo='China', endpoint='Relative error and uncertainty of calibrated HSRL backscatter channels', tier='C', basis='Lab / research instrument', affil='Shanghai Institute of Optics and Fine Mechanics, China; Shanghai Institute of Optics and Fine Mechanics, China', n='Proposes a time-varying effective system response factor to diagnose and dynamically calibrate the system constant of an airborne high-spectral-resolution lidar, using ground-based stationary observations as the reference. The calibration coefficient drifted even on the ground; in one flight, 62% of significant response-factor variations coincided with platform disturbances, roll angle most often. After dynamic calibration, mean relative errors of the parallel-polarisation and HSR channels fell below 10%, total uncertainty below 5.5%. One flight dataset and no comparison with an independent aerosol reference limit generality. Relevance: low-moderate - the drift-tracking logic is the same problem as LCS baseline drift, one instrument class up.', sub=corpus.SENS),
 dict(pmid='', doi='10.5194/acp-26-16341-2026', journal='Atmospheric Chemistry and Physics', title='Airborne and marine microplastics in the Northern Indian Ocean: decoupled pathways traced by black carbon', short='Maldives MCOH airborne vs marine microplastics deposition box micro-Raman eBC scattering advection', design='Field campaign', pm='Airborne microplastics by deposition box (MP m-3) alongside aerosol scattering and equivalent black carbon', geo='Indo-Pacific', endpoint='Airborne and marine microplastic concentration, size, polymer; coupling to eBC', tier='C', basis='Lab / research instrument', affil='Institute of Oceanology, Polish Academy of Sciences, Poland; not stated in record', n='One-month dry-season campaign at the Maldives Climate Observatory Hanimaadhoo: airborne microplastics by deposition box with optical microscopy and micro-Raman, coastal seawater sampling, plus aerosol scattering and eBC. Airborne MPs 0-10.3 MP m-3 (mean 3.1 +/- 2.8); marine MPs 120-2656 MP m-3. Size and polymer differed between reservoirs, and airborne MP variability tracked polluted advection, elevated eBC and scattering rather than sea spray. A deposition box gives a volumetric concentration only through assumed deposition velocities, and one month cannot test the seasonal sea-spray pathway. Relevance: moderate - eBC and scattering, the quantities low-cost optical sensors approximate, served as tracers for a particle class sensors cannot speciate.', sub=corpus.EXPO),
 dict(pmid='', doi='10.5194/acp-26-16373-2026', journal='Atmospheric Chemistry and Physics', title='Addressing systematic underestimation in a global ship emission inventory through improved fleet representation and fuel compliance characterization', short='Tsinghua SEIMv2.3 near-real-time AIS ship inventory sulfur compliance scrubbers PM2.5 BC underestimation 43%', design='Emission inventory', pm='Global ship PM2.5, BC and CO2 emissions from AIS activity with fuel-sulfur compliance pathways', geo='Global / multi-region', endpoint='Inventory completeness and PM2.5/BC emission bias', tier='C', basis='Model (CTM / LUR / ML)', affil='not stated in record; Tsinghua University, China', n='Updates the Ship Emission Inventory Model to SEIMv2.3 with daily ship technical-database updates and explicit post-2020 sulfur-compliance pathways (very-low-sulfur fuel versus scrubbers with heavy fuel oil), producing emissions within 3 days of AIS acquisition. Daily updates uncovered 8% and 6.2% of active bulk-carrier and container gross tonnage, up to 5.4% of global ship CO2. Assuming universal low-sulfur fuel underestimates ship PM2.5 by about 43% and BC by 15%, reaching 56% of PM2.5 in the Indian Ocean. No independent observational check of the corrected emissions is reported. Relevance: indirect - a 43% PM2.5 inventory bias propagates straight into CTM exposure surfaces near ports.', sub=corpus.EXPO),
]
